1	// HandoffController glues CsrTrigger and StateDrain. Given a retired PC and
2	// a GPR probe, decides whether to drain state and returns the populated
3	// hybrid_state_v1 if so. Pure-logic; no SystemC.
4	
5	#include "hybrid/abstract_command.hpp"
6	#include "hybrid/csr_trigger.hpp"
7	#include "hybrid/handoff_controller.hpp"
8	#include "hybrid/insn_match.h"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "insn_encoders.hpp"
12	#include "recording_bus.hpp"
13	
14	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
15	#include <doctest.h>
16	
17	#include <array>
18	#include <cstdint>
19	
20	using hybrid::test::as_bytes;
21	using hybrid::test::encode_csrrw;
22	using hybrid::test::encode_csrrwi;
23	using hybrid::test::kDmstatusHaltedAndAcked;
24	using hybrid::test::RecordingBus;
25	using RD = hybrid::ResumeDriver;
26	
27	TEST_CASE("HandoffController: EXIT csrwi triggers drain and returns state")
28	{
29	  RecordingBus bus;
30	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
31	  bus.regfile[hybrid::regno_gpr(12)] = 3;
32	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000004;
33	
34	  hybrid::CsrTrigger trigger;
35	  const std::array<uint32_t, 1> code{encode_csrrwi(0, 0x7C0, 1)};
36	  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);
37	
38	  hybrid::HandoffController h(std::move(trigger), bus);
39	  const auto state = h.on_retire(0x80000000, [](uint8_t) { return 0u; });
40	
41	  REQUIRE(state);
42	  CHECK(state->magic == HYBRID_STATE_MAGIC);
43	  CHECK(state->gpr[12] == 3);
44	  CHECK(state->pc == 0x80000004);
45	}
46	
47	TEST_CASE("HandoffController: non-trigger PC returns nullopt without drain")
48	{
49	  RecordingBus bus;
50	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
51	
52	  hybrid::CsrTrigger trigger;
53	  hybrid::HandoffController h(std::move(trigger), bus);
54	
55	  const auto state = h.on_retire(0xDEADBEEF, [](uint8_t) { return 0u; });
56	  CHECK_FALSE(state.has_value());
57	  CHECK(bus.ops.empty());
58	}
59	
60	TEST_CASE("HandoffController: ENTER csrwi never fires (vsim ignores entry)")
61	{
62	  RecordingBus bus;
63	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
64	
65	  hybrid::CsrTrigger trigger;
66	  const std::array<uint32_t, 1> code{encode_csrrwi(0, 0x7C0, 0)};
67	  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);
68	
69	  hybrid::HandoffController h(std::move(trigger), bus);
70	  const auto state = h.on_retire(0x80000000, [](uint8_t) { return 0u; });
71	  CHECK_FALSE(state.has_value());
72	  CHECK(bus.ops.empty());
73	}
