75	TEST_CASE("HandoffController: PC-mode synthetic EXIT hit drains like CSR EXIT")
76	{
77	  // PC-trigger mode populates the trigger map via add_pc_hit() instead of
78	  // scan_buffer(). HandoffController must dispatch on `kind` only and not
79	  // depend on a recorded `insn`. This is the single-test contract the PC
80	  // mode relies on.
81	  RecordingBus bus;
82	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
83	  bus.regfile[hybrid::regno_gpr(12)] = 7;
84	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000048;
85	
86	  hybrid::CsrTrigger trigger;
87	  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);
88	
89	  hybrid::HandoffController h(std::move(trigger), bus);
90	  const auto state = h.on_retire(0x80000044, [](uint8_t) { return 0u; });
91	
92	  REQUIRE(state);
93	  CHECK(state->magic == HYBRID_STATE_MAGIC);
94	  CHECK(state->gpr[12] == 7);
95	  CHECK(state->pc == 0x80000048);
96	}
97	
98	TEST_CASE("HandoffController: PC-mode hit at unrelated PC stays silent")
99	{
100	  RecordingBus bus;
101	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
102	
103	  hybrid::CsrTrigger trigger;
104	  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);
105	
106	  hybrid::HandoffController h(std::move(trigger), bus);
107	  const auto state = h.on_retire(0x80000048, [](uint8_t) { return 0u; });
108	  CHECK_FALSE(state.has_value());
109	  CHECK(bus.ops.empty());
110	}
111	
112	TEST_CASE("HandoffController: RUNTIME fires only when probed GPR == 1")
113	{
114	  RecordingBus bus;
115	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
116	
117	  hybrid::CsrTrigger trigger;
118	  const std::array<uint32_t, 1> code{encode_csrrw(0, 0x7C0, /*rs1=*/10)};
119	  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);
120	
121	  hybrid::HandoffController h(std::move(trigger), bus);
122	
123	  CHECK_FALSE(h.on_retire(0x80000000,
124	                          [](uint8_t r) { return r == 10 ? 0u : 0u; }));
125	  REQUIRE(h.on_retire(0x80000000,
126	                      [](uint8_t r) { return r == 10 ? 1u : 0u; }));
127	}
